'use strict';
// AI: below section was generated by an AI
const assert = require('node:assert/strict');
const {test} = require('node:test');
const fs = require('node:fs');
const vm = require('node:vm');
const source = fs.readFileSync('wled00/data/index.js', 'utf8');

function actualFunction(name) {
	const match = source.match(new RegExp(`async function ${name}\\([^]*?^}`, 'm'));
	assert(match, `${name} must exist`);
	return match[0];
}

function boot({skinError = false, disableWebSocket = false, cachedPresets = false} = {}) {
	const events = [], requests = [], commands = [], errors = [];
	let releasePreviews, previewsStarted;
	const previewGate = new Promise(resolve => { releasePreviews = resolve; });
	const started = new Promise(resolve => { previewsStarted = resolve; });
	let context;
	const api = {info: {ws: disableWebSocket ? -1 : 0}, state: {bri: 100}};
	context = vm.createContext({
		Date, console, WebSocket: {OPEN: 1},
		ws: null, lastinfo: {}, reqsLegal: false, jsonTimeout: null,
		isInfo: false, simplifiedUI: false, tr: 0, pmt: 1, pmtLS: cachedPresets ? 1 : 0,
		cfg: {comp: {css: true}},
		getURL: path => path,
		gId: id => id === 'tt' ? {validity: {valid: true}, value: '0'} : {style: {}},
		setTimeout: () => 1, clearTimeout() {}, clearErrorToast() {},
		showToast: message => errors.push(message),
		parseInfo: info => { context.lastinfo = info; }, readState() {},
		loadPalettes: async () => events.push('palettes'),
		loadFXData: async () => events.push('fxdata'),
		loadFX: async () => events.push('effects'),
		fetch: async (url, options) => {
			requests.push({url, method: options.method});
			events.push('state');
			return {ok: true, json: async () => api};
		},
		makeWS: () => {
			events.push('websocket');
			if (!disableWebSocket) context.ws = {readyState: 1, send: data => commands.push(JSON.parse(data))};
		},
		loadPresets: async () => events.push('presets'),
		populatePresets: () => events.push('cached-presets'),
		loadSkinCSS: async () => { if (skinError) throw new Error('Stylesheet unavailable'); },
		loadPalettesData: () => { events.push('previews'); previewsStarted(); return previewGate; },
		populatePalettes: () => events.push('render-previews')
	});
	vm.runInContext(actualFunction('requestJson') + '\n' + actualFunction('initializeControls'), context);
	const complete = context.initializeControls();
	return {context, events, requests, commands, errors, complete, started, releasePreviews};
}

test('controls send commands over WebSocket while palette previews are still loading', async () => {
	const app = boot();
	await app.started;
	assert(app.events.indexOf('websocket') < app.events.indexOf('previews'));
	assert(app.events.indexOf('presets') < app.events.indexOf('previews'));
	await app.context.requestJson({bri: 80});
	assert.equal(app.commands[0].bri, 80);
	assert.equal(app.requests.length, 1); // only the initial state GET, no HTTP command fallback
	app.releasePreviews();
	await app.complete;
	assert.deepEqual(app.errors, []);
});

test('an optional stylesheet failure does not disable WebSocket controls', async () => {
	const app = boot({skinError: true});
	await app.started;
	await app.context.requestJson({on: false});
	assert.equal(app.commands[0].on, false);
	app.releasePreviews();
	await app.complete;
	assert.deepEqual(app.errors, []);
});

test('devices without WebSockets retain HTTP control fallback', async () => {
	const app = boot({disableWebSocket: true});
	await app.started;
	await app.context.requestJson({bri: 30});
	assert.equal(app.commands.length, 0);
	assert.equal(app.requests.at(-1).method, 'post');
	app.releasePreviews();
	await app.complete;
});

test('cached presets remain available before slow previews complete', async () => {
	const app = boot({cachedPresets: true});
	await app.started;
	assert(app.events.indexOf('cached-presets') < app.events.indexOf('previews'));
	assert(!app.events.includes('presets'));
	app.releasePreviews();
	await app.complete;
});
